schemas:
DEFINE TABLE audio_snippet TYPE NORMAL SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD path ON audio_snippet TYPE string PERMISSIONS FULL;

DEFINE TABLE contain TYPE RELATION IN note OUT image_snippet | audio_snippet | video_snippet | text_snippet SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD in ON contain TYPE record<note> PERMISSIONS FULL;
DEFINE FIELD out ON contain TYPE record<image_snippet | audio_snippet | video_snippet | text_snippet> PERMISSIONS FULL;

DEFINE TABLE converge TYPE RELATION IN note | knot OUT knot SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD in ON converge TYPE record<note | knot> PERMISSIONS FULL;
DEFINE FIELD out ON converge TYPE record<knot> PERMISSIONS FULL;

DEFINE TABLE image_snippet TYPE NORMAL SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD path ON image_snippet TYPE string PERMISSIONS FULL;

DEFINE TABLE knot TYPE NORMAL SCHEMAFULL PERMISSIONS NONE;

DEFINE TABLE OVERWRITE note SCHEMALESS;

# DEFINE FIELD OVERWRITE field ON note;
DEFINE TABLE OVERWRITE script_migration SCHEMAFULL
    PERMISSIONS
        FOR select FULL
        FOR create, update, delete NONE;

DEFINE FIELD OVERWRITE script_name ON script_migration TYPE string;
DEFINE FIELD OVERWRITE executed_at ON script_migration TYPE datetime VALUE time::now() READONLY;
DEFINE FIELD OVERWRITE checksum ON script_migration TYPE option<string>;

DEFINE TABLE text_snippet TYPE NORMAL SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD content ON text_snippet TYPE string PERMISSIONS FULL;

DEFINE TABLE video_snippet TYPE NORMAL SCHEMAFULL PERMISSIONS NONE;

DEFINE FIELD path ON video_snippet TYPE string PERMISSIONS FULL;
